# Pathway Test Template

```typescript
import { PathwayAsserter, assertPathway } from '../../../test-utils/PathwayAsserter';

describe('YourFeature Pathway', () => {
    let asserter: PathwayAsserter;

    beforeEach(() => {
        asserter = new PathwayAsserter();
    });

    afterEach(async () => {
        await asserter.flush();
    });

    it('should follow expected pathway', async () => {
        // Assert expected milestones
        assertPathway(asserter, 'ComponentName.methodName', {
            requiredField: expect.any(String)
        });

        // Execute operation
        await yourOperation();

        // Flush waits for all milestones
        await asserter.flush();
    });
});
```
